import { useState } from 'react';
import { useLocation } from 'react-router-dom';
import { motion, AnimatePresence } from 'framer-motion';
import Sidebar from './Sidebar';
import TopNavbar from './TopNavbar';

export default function AppLayout({ children }) {
    const [isSidebarCollapsed, setIsSidebarCollapsed] = useState(false);
    const location = useLocation();

    return (
        <div className="flex h-screen bg-[#0f1115] text-[#e2e4e9] overflow-hidden">
            {/* Sidebar Navigation */}
            <Sidebar isCollapsed={isSidebarCollapsed} setIsCollapsed={setIsSidebarCollapsed} />

            {/* Main Content Area */}
            <div className="flex-1 flex flex-col min-w-0 overflow-hidden relative">
                <TopNavbar />

                {/* Scrollable Page Content */}
                <main className="flex-1 overflow-y-auto custom-scrollbar p-6">
                    <div className="max-w-7xl mx-auto w-full">
                        <AnimatePresence mode="wait">
                            <motion.div
                                key={location.pathname}
                                initial={{ opacity: 0, y: 15 }}
                                animate={{ opacity: 1, y: 0 }}
                                exit={{ opacity: 0, y: -15 }}
                                transition={{ duration: 0.3, ease: 'easeOut' }}
                            >
                                {children}
                            </motion.div>
                        </AnimatePresence>
                    </div>
                </main>
            </div>
        </div>
    );
}

import { useState } from 'react';
import { NavLink, useLocation } from 'react-router-dom';
import {
    LuLayoutDashboard,
    LuMap,
    LuLayers,
    LuAlertTriangle,
    LuTestTube2,
    LuTrophy,
    LuBrainCircuit,
    LuRss,
    LuServerCog,
    LuChevronLeft,
    LuChevronRight
} from 'react-icons/lu';

const NAV_ITEMS = [
    { path: '/overview', label: 'Overview', icon: LuLayoutDashboard },
    { path: '/map', label: 'Risk Atlas', icon: LuMap },
    { path: '/zones', label: 'Zone Hub', icon: LuLayers },
    { path: '/alerts', label: 'Alerts', icon: LuAlertTriangle },
    { path: '/simulation', label: 'Simulation Lab', icon: LuTestTube2 },
    { path: '/leaderboard', label: 'Leaderboard', icon: LuTrophy },
    { path: '/model-lab', label: 'Model Lab', icon: LuBrainCircuit },
    { path: '/insights', label: 'Insight Stream', icon: LuRss },
    { path: '/system', label: 'System', icon: LuServerCog },
];

export default function Sidebar({ isCollapsed, setIsCollapsed }) {
    const location = useLocation();

    return (
        <aside
            className={`
        flex flex-col h-screen bg-[#16181d] border-r border-[#1e2128]
        transition-all duration-300 ease-in-out relative z-20
        ${isCollapsed ? 'w-20' : 'w-64'}
      `}
        >
            {/* Platform Logo / Header */}
            <div className="h-16 flex items-center px-4 border-b border-[#1e2128] shrink-0">
                <div className="flex items-center gap-3 w-full overflow-hidden">
                    <div className="w-8 h-8 rounded shrink-0 bg-[#2e6041] flex items-center justify-center panel-border">
                        <svg className="w-5 h-5 text-white" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 21V5a2 2 0 00-2-2H7a2 2 0 00-2 2v16m14 0h2m-2 0h-5m-9 0H3m2 0h5M9 7h1m-1 4h1m4-4h1m-1 4h1m-5 10v-5a1 1 0 011-1h2a1 1 0 011 1v5m-4 0h4" />
                        </svg>
                    </div>
                    {!isCollapsed && (
                        <div className="flex flex-col whitespace-nowrap opacity-100 transition-opacity duration-300">
                            <span className="text-sm font-semibold tracking-wide text-[#e2e4e9] leading-tight">URI Platform</span>
                            <span className="text-[10px] text-[#7a828e] uppercase tracking-wider">Urban Risk Intel</span>
                        </div>
                    )}
                </div>
            </div>

            {/* Collapse Toggle */}
            <button
                onClick={() => setIsCollapsed(!isCollapsed)}
                className="absolute -right-3 top-20 bg-[#1e2128] border border-[#3a3f4a] rounded-full p-1 text-[#a0a5b0] hover:text-white hover:bg-[#3a3f4a] transition-colors z-30"
            >
                {isCollapsed ? <LuChevronRight size={14} /> : <LuChevronLeft size={14} />}
            </button>

            {/* Navigation Links */}
            <nav className="flex-1 overflow-y-auto py-4 px-3 space-y-1 custom-scrollbar">
                {NAV_ITEMS.map((item) => {
                    const isActive = location.pathname.startsWith(item.path);
                    const Icon = item.icon;

                    return (
                        <NavLink
                            key={item.path}
                            to={item.path}
                            className={`
                flex items-center gap-3 px-3 py-2.5 rounded-md transition-all duration-200 group
                ${isActive
                                    ? 'bg-[#1e2128] text-[#e2e4e9] border border-[#3a3f4a]'
                                    : 'text-[#9095a0] hover:bg-[#1a1c23] hover:text-[#e2e4e9] border border-transparent'}
              `}
                            title={isCollapsed ? item.label : undefined}
                        >
                            <Icon
                                size={20}
                                className={`shrink-0 ${isActive ? 'text-[#a0a5b0]' : 'text-[#7a828e] group-hover:text-[#a0a5b0]'}`}
                            />
                            {!isCollapsed && (
                                <span className="text-sm font-medium whitespace-nowrap truncate">
                                    {item.label}
                                </span>
                            )}

                            {/* Active Indicator Strip */}
                            {isActive && isCollapsed && (
                                <div className="absolute left-0 w-1 h-8 bg-[#7a828e] rounded-r-md" />
                            )}
                        </NavLink>
                    );
                })}
            </nav>

            {/* Footer Info */}
            <div className="p-4 border-t border-[#1e2128] shrink-0">
                {!isCollapsed ? (
                    <div className="text-xs text-[#5e6470] font-mono">
                        v2.0.4.stable<br />
                        Engine: Live
                    </div>
                ) : (
                    <div className="text-center font-mono text-[10px] text-[#5e6470]">
                        v2
                    </div>
                )}
            </div>
        </aside>
    );
}

import { useState, useEffect } from 'react';
import {
  ResponsiveContainer, PieChart, Pie, Cell,
  BarChart, Bar, XAxis, YAxis, Tooltip as RechartsTooltip,
  CartesianGrid, Legend
} from 'recharts';
import CountUp from 'react-countup';
import { LuActivity, LuAlertTriangle, LuMapPin, LuServerCog } from 'react-icons/lu';

const COLORS = ['#2e6041', '#3b5060', '#803030']; // Safe, System, Danger
const RISK_DIST_DATA = [
  { name: 'Air Quality', value: 45 },
  { name: 'Water Systems', value: 30 },
  { name: 'Urban Density', value: 25 },
];

const FORECAST_DATA = [
  { name: 'North Zone', current: 65, predicted: 78 },
  { name: 'South Zone', current: 42, predicted: 45 },
  { name: 'East Zone', current: 85, predicted: 82 },
  { name: 'West Zone', current: 55, predicted: 68 },
  { name: 'Central', current: 72, predicted: 88 },
];

export default function Overview() {
  const [data, setData] = useState(null);

  // Simulate data fetch
  useEffect(() => {
    setTimeout(() => {
      setData({
        healthScore: 68,
        aiConfidence: 94.2,
        activeZones: 124,
        highRiskZones: 18,
        anomalyZones: 3
      });
    }, 800);
  }, []);

  if (!data) {
    return (
      <div className="h-full flex items-center justify-center">
        <div className="flex flex-col items-center gap-4">
          <div className="w-8 h-8 rounded-full border-2 border-[#1e2128] border-t-[#a0a5b0] animate-spin"></div>
          <span className="text-[#5e6470] font-mono text-sm tracking-widest uppercase">Initializing Core...</span>
        </div>
      </div>
    );
  }

  return (
    <div className="flex flex-col gap-6 pb-12">

      {/* Header */}
      <div className="flex flex-col gap-1">
        <h2 className="text-2xl font-semibold text-[#e2e4e9] tracking-tight">Executive Control Room</h2>
        <p className="text-sm text-[#9095a0]">High-level intelligence and real-time risk distribution across the city.</p>
      </div>

      {/* TOP SECTION: Hero Control Panel */}
      <div className="grid grid-cols-1 md:grid-cols-4 gap-6">

        {/* City Health Score - Large Widget */}
        <div className="md:col-span-1 panel-bg panel-border rounded-xl p-6 flex flex-col justify-between relative overflow-hidden">
          <div className="absolute top-0 right-0 p-4 opacity-5">
            <LuActivity size={120} />
          </div>
          <div>
            <h3 className="text-[#9095a0] text-xs font-semibold uppercase tracking-wider mb-1">City Health Index</h3>
            <p className="text-[#5e6470] text-[10px] pr-8">Aggregated risk quotient. Lower is better.</p>
          </div>
          <div className="mt-6 flex items-baseline gap-2">
            <span className="text-5xl font-bold metallic-text tracking-tighter">
              <CountUp end={data.healthScore} duration={2} />
            </span>
            <span className="text-[#7a828e] font-mono text-sm">/ 100</span>
          </div>
          <div className="w-full bg-[#1e2128] h-1.5 rounded-full mt-4 overflow-hidden">
            <div className="bg-[#8c7322] h-full rounded-full" style={{ width: `${data.healthScore}%` }}></div>
          </div>
        </div>

        {/* Mini KPI Cards Grid */}
        <div className="md:col-span-3 grid grid-cols-2 md:grid-cols-4 gap-4">

          <KPICard
            title="AI Confidence"
            value={<><CountUp end={data.aiConfidence} decimals={1} duration={1.5} />%</>}
            icon={LuServerCog}
            trend="+0.4%"
            trendUp={true}
          />

          <KPICard
            title="Active Zones"
            value={<CountUp end={data.activeZones} duration={2} />}
            icon={LuMapPin}
            trend="Online"
            trendUp={true}
          />

          <KPICard
            title="High Risk Zones"
            value={<CountUp end={data.highRiskZones} duration={1.5} />}
            icon={LuActivity}
            trend="+2 from D-1"
            trendUp={false}
            alert={true}
          />

          <KPICard
            title="Anomaly Detects"
            value={<CountUp end={data.anomalyZones} duration={1} />}
            icon={LuAlertTriangle}
            trend="Needs Review"
            trendUp={false}
            alert={true}
          />

        </div>
      </div>

      {/* MIDDLE SECTION: Analytics Grid */}
      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">

        {/* Donut Chart: Risk Distribution */}
        <div className="lg:col-span-1 panel-bg panel-border rounded-xl p-5 flex flex-col">
          <h3 className="text-[#e2e4e9] text-sm font-medium tracking-wide mb-4 flex items-center justify-between">
            Risk Distribution
            <span className="bg-[#1e2128] text-[#9095a0] text-[10px] px-2 py-0.5 rounded">Live</span>
          </h3>
          <div className="flex-1 h-[240px]">
            <ResponsiveContainer width="100%" height="100%">
              <PieChart>
                <Pie
                  data={RISK_DIST_DATA}
                  innerRadius={65}
                  outerRadius={90}
                  paddingAngle={4}
                  dataKey="value"
                  stroke="none"
                >
                  {RISK_DIST_DATA.map((entry, index) => (
                    <Cell key={`cell-${index}`} fill={COLORS[index % COLORS.length]} />
                  ))}
                </Pie>
                <RechartsTooltip
                  contentStyle={{ backgroundColor: '#1a1c23', borderColor: '#3a3f4a', borderRadius: '8px', color: '#e2e4e9' }}
                  itemStyle={{ color: '#e2e4e9' }}
                />
                <Legend verticalAlign="bottom" height={36} iconType="circle" wrapperStyle={{ fontSize: '12px', color: '#9095a0' }} />
              </PieChart>
            </ResponsiveContainer>
          </div>
        </div>

        {/* Bar Chart: Horizon Comparison */}
        <div className="lg:col-span-2 panel-bg panel-border rounded-xl p-5 flex flex-col">
          <h3 className="text-[#e2e4e9] text-sm font-medium tracking-wide mb-4 flex items-center justify-between">
            Forecast Horizon: Current vs D+7
            <span className="bg-[#2e6041]/20 text-[#2e6041] border border-[#2e6041]/30 text-[10px] px-2 py-0.5 rounded">Model: UR-v4</span>
          </h3>
          <div className="flex-1 h-[240px]">
            <ResponsiveContainer width="100%" height="100%">
              <BarChart data={FORECAST_DATA} margin={{ top: 10, right: 10, left: -20, bottom: 0 }}>
                <CartesianGrid strokeDasharray="3 3" stroke="#1e2128" vertical={false} />
                <XAxis dataKey="name" stroke="#5e6470" fontSize={12} tickLine={false} axisLine={false} />
                <YAxis stroke="#5e6470" fontSize={12} tickLine={false} axisLine={false} />
                <RechartsTooltip
                  cursor={{ fill: '#1e2128', opacity: 0.4 }}
                  contentStyle={{ backgroundColor: '#1a1c23', borderColor: '#3a3f4a', borderRadius: '8px', color: '#e2e4e9' }}
                />
                <Legend wrapperStyle={{ fontSize: '12px', color: '#9095a0' }} />
                <Bar dataKey="current" name="Current (D+0)" fill="#3b5060" radius={[2, 2, 0, 0]} barSize={24} />
                <Bar dataKey="predicted" name="Predicted (D+7)" fill="#803030" radius={[2, 2, 0, 0]} barSize={24} />
              </BarChart>
            </ResponsiveContainer>
          </div>
        </div>
      </div>

      {/* BOTTOM SECTION: Live Feed Strip */}
      <div className="panel-bg panel-border rounded-xl p-4 overflow-hidden relative">
        <div className="absolute left-0 top-0 bottom-0 w-24 bg-gradient-to-r from-[#16181d] to-transparent z-10 flex items-center px-4">
          <span className="text-[10px] font-bold tracking-widest text-[#9095a0] uppercase">Live Intel</span>
        </div>
        <div className="absolute right-0 top-0 bottom-0 w-12 bg-gradient-to-l from-[#16181d] to-transparent z-10" />

        <div className="flex gap-6 animate-pulse pl-24">
          <FeedItem time="10:42" msg="AI Model UR-v4 retraining completed successfully. Drift: 0.02" type="system" />
          <FeedItem time="10:38" msg="Central Zone PM2.5 anomaly detected. Expected rise in D+1." type="warning" />
          <FeedItem time="10:15" msg="East Zone water infrastructure stress reduced by 4%." type="success" />
        </div>
      </div>

    </div>
  );
}

function KPICard({ title, value, icon: Icon, trend, trendUp, alert }) {
  return (
    <div className={`
      panel-bg panel-border rounded-xl p-4 flex flex-col justify-between
      ${alert ? 'border-[#803030]/30 relative overflow-hidden' : ''}
    `}>
      {alert && <div className="absolute top-0 right-0 w-16 h-16 bg-[#803030]/5 rounded-bl-[100px] pointer-events-none"></div>}
      <div className="flex items-center justify-between mb-2">
        <span className="text-[#9095a0] text-xs font-medium truncate pr-2">{title}</span>
        <Icon size={14} className={alert ? 'text-[#803030]' : 'text-[#5e6470]'} />
      </div>
      <div className="text-2xl font-semibold text-[#e2e4e9] tracking-tight">{value}</div>
      <div className="mt-2 text-[10px] font-mono flex items-center gap-1">
        <span className={trendUp ? 'text-[#2e6041]' : (alert ? 'text-[#803030]' : 'text-[#8c7322]')}>
          {trend}
        </span>
      </div>
    </div>
  );
}

function FeedItem({ time, msg, type }) {
  const colors = {
    system: 'text-[#3b5060]',
    warning: 'text-[#8c7322]',
    success: 'text-[#2e6041]'
  };

  return (
    <div className="flex items-center gap-3 shrink-0">
      <span className="text-[#5e6470] font-mono text-[10px] border border-[#3a3f4a] bg-[#1a1c23] px-1.5 py-0.5 rounded">
        {time}
      </span>
      <span className={`w-1.5 h-1.5 rounded-full ${colors[type].replace('text-', 'bg-')}`}></span>
      <span className="text-sm text-[#a0a5b0] whitespace-nowrap">{msg}</span>
    </div>
  );
}

import { useState } from 'react';
import { MapContainer, TileLayer, CircleMarker, Popup, useMap } from 'react-leaflet';
import 'leaflet/dist/leaflet.css';
import { LuActivity, LuInfo, LuMap } from 'react-icons/lu';

// Dummy zones
const ZONES = [
    { id: 1, name: "Industrial Corridor East", lat: 28.679, lng: 77.25, risk: 85, trend: "Rising" },
    { id: 2, name: "Central Tech Park", lat: 28.6139, lng: 77.209, risk: 45, trend: "Stable" },
    { id: 3, name: "North Residential", lat: 28.7041, lng: 77.1025, risk: 65, trend: "Decreasing" },
    { id: 4, name: "South Market Hub", lat: 28.5355, lng: 77.263, risk: 78, trend: "Rising" }
];

export default function RiskAtlas() {
    const [selectedZone, setSelectedZone] = useState(null);
    const [horizon, setHorizon] = useState('d1'); // d1, d3, d7

    return (
        <div className="flex flex-col h-[calc(100vh-8rem)] gap-4 pb-4">

            {/* Header Controls */}
            <div className="flex items-center justify-between shrink-0">
                <div>
                    <h2 className="text-2xl font-semibold text-[#e2e4e9] tracking-tight">Risk Atlas</h2>
                    <p className="text-sm text-[#9095a0]">Spatial intelligence and geographic distribution mapping.</p>
                </div>

                {/* Forecast Toggle */}
                <div className="flex bg-[#16181d] border border-[#1e2128] rounded-lg p-1">
                    {['d1', 'd3', 'd7'].map((timeStr, idx) => {
                        const label = idx === 0 ? 'D+1' : idx === 1 ? 'D+3' : 'D+7';
                        return (
                            <button
                                key={timeStr}
                                onClick={() => setHorizon(timeStr)}
                                className={`
                  px-4 py-1.5 text-xs font-semibold rounded-md transition-colors
                  ${horizon === timeStr
                                        ? 'bg-[#1e2128] text-[#e2e4e9] shadow-sm'
                                        : 'text-[#5e6470] hover:text-[#9095a0]'}
                `}
                            >
                                {label}
                            </button>
                        )
                    })}
                </div>
            </div>

            {/* Map Container & Sidebar */}
            <div className="flex-1 min-h-0 flex gap-4">

                {/* Main Map */}
                <div className="flex-1 panel-bg panel-border rounded-xl overflow-hidden relative">

                    <MapContainer
                        center={[28.6139, 77.209]}
                        zoom={11}
                        className="w-full h-full bg-[#16181d]"
                        zoomControl={false}
                    >
                        {/* Custom dark theme tile layer (CartoDB Dark Matter) */}
                        <TileLayer
                            url="https://{s}.basemaps.cartocdn.com/dark_all/{z}/{x}/{y}{r}.png"
                            attribution='&copy; <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a> contributors &copy; <a href="https://carto.com/attributions">CARTO</a>'
                        />

                        {ZONES.map(zone => (
                            <CircleMarker
                                key={zone.id}
                                center={[zone.lat, zone.lng]}
                                radius={zone.risk > 70 ? 12 : 8}
                                pathOptions={{
                                    fillColor: zone.risk > 75 ? '#803030' : zone.risk > 50 ? '#8c7322' : '#2e6041',
                                    color: 'transparent',
                                    fillOpacity: 0.7,
                                }}
                                eventHandlers={{
                                    click: () => setSelectedZone(zone)
                                }}
                            >
                                {/* <Popup className="custom-popup">
                  <div className="font-semibold">{zone.name}</div>
                  <div className="text-xs mt-1">Risk Score: {zone.risk}</div>
                </Popup> */}
                            </CircleMarker>
                        ))}
                    </MapContainer>

                    {/* Overlay Map Controls/Legend */}
                    <div className="absolute bottom-4 left-4 z-[400] bg-[#1a1c23]/90 backdrop-blur border border-[#3a3f4a] p-3 rounded-lg pointer-events-none">
                        <h4 className="text-[10px] uppercase font-bold text-[#9095a0] mb-2 tracking-wider">Risk Levels</h4>
                        <div className="flex flex-col gap-2 scale-90 origin-left">
                            <div className="flex items-center gap-2">
                                <div className="w-3 h-3 rounded-full bg-[#803030]"></div>
                                <span className="text-xs text-[#a0a5b0]">Critical (75-100)</span>
                            </div>
                            <div className="flex items-center gap-2">
                                <div className="w-3 h-3 rounded-full bg-[#8c7322]"></div>
                                <span className="text-xs text-[#a0a5b0]">Elevated (50-74)</span>
                            </div>
                            <div className="flex items-center gap-2">
                                <div className="w-3 h-3 rounded-full bg-[#2e6041]"></div>
                                <span className="text-xs text-[#a0a5b0]">Nominal (0-49)</span>
                            </div>
                        </div>
                    </div>
                </div>

                {/* Selected Zone Side Panel */}
                <div className={`
          w-80 panel-bg panel-border rounded-xl p-5 flex flex-col transition-all duration-300
          ${selectedZone ? 'translate-x-0 opacity-100' : 'translate-x-[20px] opacity-0 pointer-events-none absolute right-6 hidden'}
        `}>
                    {selectedZone && (
                        <>
                            <div className="flex justify-between items-start mb-6">
                                <div>
                                    <h3 className="text-lg font-semibold text-[#e2e4e9] leading-tight mb-1">{selectedZone.name}</h3>
                                    <span className="text-[10px] text-[#5e6470] uppercase tracking-wider font-mono">ID: ZNE-{selectedZone.id.toString().padStart(4, '0')}</span>
                                </div>
                                <button onClick={() => setSelectedZone(null)} className="text-[#5e6470] hover:text-[#e2e4e9] p-1">
                                    ✕
                                </button>
                            </div>

                            {/* Quick Pulse / Risk indicator */}
                            <div className="bg-[#1a1c23] border border-[#3a3f4a] rounded-lg p-4 flex flex-col items-center justify-center mb-6">
                                <span className="text-[10px] uppercase text-[#7a828e] font-semibold tracking-widest mb-2">Composite Risk</span>
                                <div className={`text-4xl font-bold ${selectedZone.risk > 75 ? 'text-[#803030]' : selectedZone.risk > 50 ? 'text-[#8c7322]' : 'text-[#2e6041]'
                                    }`}>
                                    {selectedZone.risk}
                                </div>
                            </div>

                            {/* Data Rows */}
                            <div className="flex flex-col gap-4 text-sm flex-1">
                                <div className="flex items-center justify-between border-b border-[#1e2128] pb-2">
                                    <span className="text-[#7a828e]">Forecast Trend</span>
                                    <span className="text-[#a0a5b0]">{selectedZone.trend}</span>
                                </div>
                                <div className="flex items-center justify-between border-b border-[#1e2128] pb-2">
                                    <span className="text-[#7a828e]">Primary Factor</span>
                                    <span className="text-[#a0a5b0]">Industrial Particulates</span>
                                </div>
                                <div className="flex items-center justify-between border-b border-[#1e2128] pb-2">
                                    <span className="text-[#7a828e]">Confidence</span>
                                    <span className="text-[#a0a5b0]">89.4%</span>
                                </div>
                            </div>

                            {/* Action Button */}
                            <button className="w-full mt-4 bg-[#3a3f4a] hover:bg-[#5e6470] text-[#e2e4e9] py-2 rounded-md text-sm font-medium transition-colors flex justify-center items-center gap-2">
                                <LuActivity size={16} /> Open Deep Analysis
                            </button>
                        </>
                    )}
                </div>

            </div>

        </div>
    );
}
